% Time
CT = str2num(CatsData{21, 1}.Data{1, end}); % Cycle Time
dt = CT/(size(ANKa,1)-1);
time = (0:size(ANKa,1)-1)'*dt;
DutyFactor = str2num(CatsData{21, 1}.Data{1, end-1}); % DF is a column before CycleTime



%% MT Mechanical Properties
load('MTMP.mat');
Data_MTMP = table2array(MTMP(1:end, 1:end));


%% MT Length Velocity & MomentArm
load(['MTLengthVelocityMomentArm_', numTrialStr, '.mat']);


%% Maximum MT length of reference model & Maximum MT length of all cats for scaling tendon and fascicle length 
load('MaxMTLength_ref.mat');
load('MaxMTLengthCats.mat');

LegLength_ref= 268.7000/1000; %m

%% Computation of muscle force and moment
% Muscle Number (mn = 1 to 11)

% activation for 40 muscles
a = xopt;

for mn = 1:size(MTLengthVelocityMomentArm,1)

% Musculotendon length and velocity
LMT = MTLengthVelocityMomentArm{mn, 1}.Length;
VMT = MTLengthVelocityMomentArm{mn, 1}.Velocity;

% Moment Arm of Musculotendon
MAMT = MTLengthVelocityMomentArm{mn, 1}.MomentArm;


% Muscle mechanical parameters 
LF0 = Data_MTMP(mn,4)*(MaxMTLengthCats{mn, numCat}/MaxMTLength_ref{mn,1});       % Optimal fascicle length (mm) scaled by maximum MT length of all trials of one cat divided by maximum MT length of generic cat
%LF0 = Data_MTMP(mn,4)*(max(LMT)/MaxMTLength_ref{mn,1});
LF0 = LF0/1000;                                                                  % mm to m
Vmax = -Data_MTMP(mn,7);                                                         % Maximum velocity (m/s)
SO = Data_MTMP(mn,6);                                                            % Percentage of slow-twitch fibres
if SO <= 1, SO = 4;  end 
PCSA = Data_MTMP(mn,2)*(LegLength/LegLength_ref)^2;                              % Physiological cross sectional area (cm^2) scaled by (leg length of current cat/leg length of generic cat)^2
PA = Data_MTMP(mn,3);                                                            % Pennation angle (rad)
LT0 = Data_MTMP(mn,5)*(MaxMTLengthCats{mn, numCat}/MaxMTLength_ref{mn,1});       % Tendon slack length (mm) scaled by maximum MT length of all trials of one cat divided by maximum MT length of generic cat
%LT0 = Data_MTMP(mn,5)*(max(LMT)/MaxMTLength_ref{mn,1});
LT0 = LT0/1000;                                                                  % mm to m
g = 9.806;                                                                       % Gravity acceleration (m/s^2)
FM_max = Data_MTMP(mn,8)*(LegLength/LegLength_ref)^2;                            % Maximum muscle force (Newton) scaled by (leg length of current cat/leg length of generic cat)^2
aV_FMmax = 0.00915*SO-0.00467;                                                   % aV/Fm_max = 0.00915· S − 0.00467 (normalized by Fm_max)
aV = aV_FMmax*FM_max;                                                            % aV = aV_FMmax*FM_max
% aV = Data_MTMP(mn,9);                                                          % Not sure
Max_LMT = max(LMT);                                                              % Maximum musculotendon length (this value previously used to compute LT0, but here we have LT0)

load(['TS_', numTrialStr, '.mat']);
[LT, LF, VF, NLF, NVF, FPE, FCE_L, FCE_V, FM, FMT] = MTForce(a(mn), time(TS), LMT(TS), VMT(TS), LT0, LF0, aV, Vmax, FM_max, PA, Max_LMT);


% Muscle fatigue
  Muscle_Fatigue(mn,1) = (FMT/PCSA)^3; %(1)
  
  LF_9(mn,1) = LF;
  VF_9(mn,1) = VF;
  NLF_9(mn,1) = NLF;
  NVF_9(mn,1) = NVF;
  FPE_9(mn,1) = FPE;
  FCE_L_9(mn,1) = FCE_L;
  FCE_V_9(mn,1) = FCE_V;
  FM_9(mn,1) = FM;
  FMT_9(mn,1) = FMT;
  
% Moment of Musculotendon
MMT_Hip_9(:,mn) = MAMT(TS,1).*FMT;
MMT_Knee_9(:,mn) = MAMT(TS,2).*FMT;
MMT_Ankle_9(:,mn) = MAMT(TS,3).*FMT;
end


MMT_J(1,1) = sum(MMT_Hip_9); % Moment of all musculotendons around Hip 
MMT_J(1,2) = sum(MMT_Knee_9);    % Moment of all musculotendons around Knee 
MMT_J(1,3) = sum(MMT_Ankle_9);    % Moment of all musculotendons around Ankle 


% Total muscle fatigue
  Total_Muscle_Fatigue = sum(Muscle_Fatigue);       %(1)

end











